  'inv.how.issued': ['Linhas e dados de recebimento ficam copiados e não mudam. O financeiro pode devolver para rascunho com um motivo, que vai por e-mail.', 'Lines and payment details are copied and no longer change. Finance can return it to draft with a reason, sent by email.', 'Las líneas y los datos de cobro quedan copiados y no cambian. Finanzas puede devolverla a borrador con un motivo, que va por correo.'],
