  'inv.payee.dialogDesc': ['Os seus dados como pessoa física: quem recebe é sempre você, nunca uma empresa. Mudar depois não altera invoices já emitidas.', 'Your details as an individual: the payee is always you, never a company. Changing them later does not alter issued invoices.', 'Tus datos como persona física: quien cobra eres siempre tú, nunca una empresa. Cambiarlos después no altera invoices ya emitidas.'],
